std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(result.begin(), result.end(), result.begin(),
                   [this](double /*unused*/) { return 0.0; });
    for (std::size_t c = 0; c < cols_; ++c) {
        result[c] = std::accumulate(
            data_.begin() + static_cast<std::ptrdiff_t>(c),
            data_.end() + static_cast<std::ptrdiff_t>(c) -
                static_cast<std::ptrdiff_t>(cols_ * rows_),
            0.0,
            [this, c](double acc, double /*val*/) {
                return acc + at((&val - &data_.front()) / cols_, c);
            });
    }
    return result;
}

